'use client';
import { useEffect, useRef, useState } from 'react';
import { cx } from '../lib/cx';
import { useCopied } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { enter, Fold, Spin, SwapIcon, Tip, useGrow } from '../lib/motion';
import '../designme.css';
import './terminal-stream.css';

/** ok is green, bad is red, muted is grey */
export type TerminalTone = 'ok' | 'bad' | 'muted';
/** A line of output, or { text, tone } to colour it */
export type TerminalLine = string | { text: string; tone?: TerminalTone };

export interface TerminalCommand {
  kind?: 'command';
  /** Like "npm run build" */
  command: string;
  /** What it printed so far. Longer than `tail` + 1 lines, all but the last `tail` fold behind "Show N more lines" */
  output?: TerminalLine[];
  /** running shows a spinner; ok a check; failed its exit code in red; stopped a Stopped tag */
  status: 'running' | 'ok' | 'failed' | 'stopped';
  /** Shown when it failed, as "Exit 1" */
  exitCode?: number;
  /** How long it has taken, like "6.1 s" */
  duration?: string;
}

/** A line from the agent between commands, like what went wrong and what it will do about it */
export interface TerminalNote {
  kind: 'note';
  text: string;
}

/** A file the agent edits between commands */
export interface TerminalEdit {
  kind: 'edit';
  file: string;
  /** Lines added and removed, shown once it is done */
  added?: number;
  removed?: number;
  /** The changed lines, each starting with "-" (removed, in red) or "+" (added, in green), shown under it once it is done */
  diff?: string[];
  status?: 'running' | 'done' | 'stopped';
}

export type TerminalEntry = TerminalCommand | TerminalNote | TerminalEdit;
export type TerminalStatus = 'running' | 'passed' | 'failed' | 'stopped';

export interface TerminalStreamProps {
  /** The working directory, shown in the header, like "~/acme/web" */
  cwd: string;
  /** Commands, notes and edits, oldest first */
  entries: TerminalEntry[];
  /** The run as a whole. Left out, it is running while any entry runs, then failed if the last command failed, else passed */
  status?: TerminalStatus;
  /** How long the run has taken, like "0:18". Shown beside Running in the header while it runs */
  elapsed?: string;
  /** The line at the foot once the run is over. Defaults to "Ran 3 commands", counting each command once however many times
      it ran (how it went is the header's tag, and a finished line has no clock); false hides it */
  summary?: string | false;
  /** How many lines a folded output keeps showing */
  tail?: number;
  /** Adds the Stop button while the run is going */
  onStop?: () => void;
  /** Called with the whole run as text when it is copied */
  onCopy?: (text: string) => void;
  labels?: { running?: string; passed?: string; failed?: string; stopped?: string; stop?: string; copy?: string; copied?: string; more?: (n: number) => string; fewer?: string; edit?: string };
  className?: string;
}

const lineOf = (l: TerminalLine) => (typeof l === 'string' ? { text: l, tone: undefined } : l);
const TONE: Record<TerminalTone, string> = { ok: 'dm-ok', bad: 'dm-bad', muted: 'dm-mu' };
const isNote = (e: TerminalEntry): e is TerminalNote => e.kind === 'note';
const isEdit = (e: TerminalEntry): e is TerminalEdit => e.kind === 'edit';

function Lines({ lines }: { lines: TerminalLine[] }) {
  return <code className="dm-tmx-o">{lines.map((l, i) => { const { text, tone } = lineOf(l); return <span key={i} className={cx('dm-tmx-l', tone && TONE[tone])}>{text}</span>; })}</code>;
}

/** The shell commands an agent runs, as a compact terminal: the working directory and how the run is going in the header,
    each command with its output streaming in under it and an exit code or a check with how long it took, and a summary
    at the foot once it is over. Long output folds to its last lines. The terminal grows with its output, eased, up to 420px
    (set `max-height` on it and on its `.dm-grow` to change that); then its output scrolls, staying on the newest line unless
    the reader has scrolled up. The output is code, in mono; everything around it is in the interface's type. */
export function TerminalStream({ cwd, entries, status, elapsed, summary, tail = 4, onStop, onCopy, labels = {}, className }: TerminalStreamProps) {
  const L = { running: 'Running', passed: 'Passed', failed: 'Failed', stopped: 'Stopped', stop: 'Stop', copy: 'Copy', copied: 'Copied to clipboard',
    more: (n: number) => `Show ${n} more line${n === 1 ? '' : 's'}`, fewer: 'Show fewer lines', edit: 'Edit', ...labels };
  const [open, setOpen] = useState<Set<number>>(() => new Set());
  const [copied, copy] = useCopied();
  const cmds = entries.filter((e): e is TerminalCommand => !isNote(e) && !isEdit(e));
  const busy = entries.some(e => !isNote(e) && e.status === 'running');
  const last = cmds[cmds.length - 1];
  const state: TerminalStatus = status ?? (busy ? 'running' : last?.status === 'failed' ? 'failed' : last?.status === 'stopped' ? 'stopped' : 'passed');
  const running = state === 'running';
  const n = new Set(cmds.map(c => c.command)).size;
  // how it went is the header's tag, so the summary doesn't say it again
  const foot = summary !== undefined ? summary : `Ran ${n} command${n === 1 ? '' : 's'}`;
  // no room is kept for output still to come (owner, 17 Nov): it grows as lines arrive (as grow() on the site)
  const [root, inner] = useGrow();
  // while it streams, its lines open their own height (the CSS, where the browser can ease to an auto height), so the
  // terminal follows them exactly and never springs behind them (data-grow-follow)
  const [opens] = useState(() => typeof CSS !== 'undefined' && CSS.supports('interpolate-size', 'allow-keywords') && !(typeof matchMedia !== 'undefined' && matchMedia('(prefers-reduced-motion: reduce)').matches));
  const toggle = (i: number) => setOpen(s => { const t = new Set(s); if (t.has(i)) t.delete(i); else t.add(i); return t; });
  // new output keeps the log on its newest line, unless the reader has scrolled up; then it stays where they are
  const log = useRef<HTMLDivElement>(null), pinned = useRef(true);
  useEffect(() => {
    const el = log.current; if (!el) return;
    const stick = () => { if (pinned.current) el.scrollTop = el.scrollHeight; };
    const mo = new MutationObserver(stick); mo.observe(el, { childList: true, subtree: true, characterData: true });
    const ro = new ResizeObserver(stick); ro.observe(el);
    // a line that arrives opens its height (the CSS), so once the log scrolls it stays on that line as it opens
    let raf = 0, till = 0;
    const follow = () => { till = performance.now() + 240; if (raf) return; const f = (t: number) => { stick(); raf = t < till ? requestAnimationFrame(f) : 0; }; raf = requestAnimationFrame(f); };
    el.addEventListener('animationstart', follow);
    stick();
    return () => { mo.disconnect(); ro.disconnect(); el.removeEventListener('animationstart', follow); cancelAnimationFrame(raf); };
  }, []);

  const text = () => entries.flatMap(e => isNote(e) ? ['# ' + e.text]
    : isEdit(e) ? [`# ${L.edit} ${e.file}${e.added !== undefined || e.removed !== undefined ? ` (+${e.added ?? 0} −${e.removed ?? 0})` : ''}`, ...(e.status === 'done' || e.status === undefined ? e.diff ?? [] : [])]
    : ['$ ' + e.command, ...(e.output ?? []).map(l => lineOf(l).text)]).join('\n');
  const copyAll = () => { const t = text(); copy(t); onCopy?.(t); };

  return (
    <div data-dm="" ref={root} data-grow-follow={running && opens ? '' : undefined} className={cx('dm-tmx dm-panel dm-growing dm-mx-grow dm-mx-ic', running && 'dm-live', className)} style={{ containerType: 'inline-size' }}>
      <div ref={inner} className="dm-grow">
      <div className="dm-tmx-h">
        <span className="dm-tmx-ic"><Icon name="term" /></span>
        <span className="dm-tmx-cwd">{cwd}</span>
        <span className={cx('dm-tmx-st', state === 'passed' && 'dm-ok', state === 'failed' && 'dm-bad')}>
          <span className="dm-g"><SwapIcon id={running ? 'run' : state}>{running ? <Spin /> : <Icon name={state === 'passed' ? 'check' : 'stop'} size="xs" />}</SwapIcon></span>
          <span className={cx('dm-tmx-sv dm-num', running && 'dm-shim')}>{running ? (elapsed ? `${L.running} · ${elapsed}` : L.running) : L[state]}</span>
        </span>
        <span className="dm-sp" />
        {running && onStop && <button type="button" className="dm-pill dm-ghost dm-sm dm-tmx-stop dm-mx-press" aria-label="Stop the running command" onClick={onStop}><Icon name="stop" size="xs" />{L.stop}</button>}
        <Tip label={copied ? L.copied : L.copy} open={copied}>
          <button type="button" className={cx('dm-ib dm-tmx-cp dm-mx-press', copied && 'dm-copied')} aria-label="Copy the output" onClick={copyAll}><SwapIcon id={copied ? 'check' : 'copy'}><Icon name={copied ? 'check' : 'copy'} /></SwapIcon></button>
        </Tip>
      </div>
      <div ref={log} className="dm-tmx-body" role="log" aria-label="Terminal output" tabIndex={0}
        onScroll={e => { const el = e.currentTarget; pinned.current = el.scrollTop + el.clientHeight >= el.scrollHeight - 24; }}>
        {entries.map((e, i) => {
          // each entry, line and edit opens its own height as it arrives (the CSS), so the log never pulses; the agent's newest
          // note shimmers while the run goes on: it is still working it out
          if (isNote(e)) return <div key={i} className="dm-tmx-note"><Icon name="spark" size="xs" /><span className={cx(running && i === entries.length - 1 && 'dm-shim')}>{e.text}</span></div>;
          if (isEdit(e)) return (
            <div key={i} className="dm-tmx-blk" data-s={e.status === 'stopped' ? 'stop' : 'edit'}>
              <div className="dm-tmx-cmd"><span className="dm-tmx-p"><Icon name="edit" size="xs" /></span><code className="dm-tmx-c">{L.edit} {e.file}</code>
                <span className="dm-tmx-m">{e.status === 'running' || e.status === 'stopped' ? <span className="dm-g"><SwapIcon id={e.status}>{e.status === 'running' ? <Spin /> : <span className="dm-tag">{L.stopped}</span>}</SwapIcon></span>
                  : <>{e.added !== undefined && <span className="dm-add">+{e.added}</span>}{e.removed !== undefined && <span className="dm-del">−{e.removed}</span>}</>}</span>
              </div>
              {e.status !== 'running' && e.status !== 'stopped' && e.diff && e.diff.length > 0 && (
                <code className="dm-tmx-df">{e.diff.map((d, j) => { const x = enter(j * 90); return <span key={j} className={cx(d[0] === '+' && 'dm-a', d[0] === '-' && 'dm-d', x.className)} style={x.style}>{d}</span>; })}</code>
              )}
            </div>
          );
          const out = e.output ?? [], fold = out.length > tail + 1, hidden = fold ? out.slice(0, out.length - tail) : [], shown = fold ? out.slice(out.length - tail) : out, isOpen = open.has(i);
          return (
            <div key={i} className="dm-tmx-blk" data-s={e.status === 'running' ? 'run' : e.status === 'ok' ? 'ok' : e.status === 'failed' ? 'bad' : 'stop'}>
              <div className="dm-tmx-cmd">
                <code className="dm-tmx-p">$</code><code className="dm-tmx-c">{e.command}</code>
                <span className="dm-tmx-m">
                  <span className="dm-g"><SwapIcon id={e.status}>{e.status === 'running' ? <Spin /> : e.status === 'ok' ? <span className="dm-ok"><Icon name="check" size="xs" /></span>
                    : e.status === 'failed' ? <span className="dm-tag dm-bad">Exit {e.exitCode ?? 1}</span> : <span className="dm-tag">{L.stopped}</span>}</SwapIcon></span>
                  {e.duration && <span className="dm-t dm-num">{e.duration}</span>}
                </span>
              </div>
              {fold && <button type="button" className="dm-tmx-more dm-mx-press" aria-expanded={isOpen} onClick={() => toggle(i)}><Icon name="chev-d" size="xs" /><span>{isOpen ? L.fewer : L.more(hidden.length)}</span><i className="dm-sp" /></button>}
              {fold && <Fold open={isOpen}><Lines lines={hidden} /></Fold>}
              {shown.length > 0 && <Lines lines={shown} />}
            </div>
          );
        })}
      </div>
      <Fold open={!running && foot !== false} className="dm-tmx-ff">
        <div className={cx('dm-tmx-f', state === 'stopped' && 'dm-stop', state === 'failed' && 'dm-bad')}>
          <span className="dm-g"><Icon name={state === 'passed' ? 'ok' : state === 'failed' ? 'alert' : 'stop'} /></span>
          <span className="dm-tmx-fs dm-num">{foot || ''}</span>
        </div>
      </Fold>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Terminal stream ---------- */
/* the shell commands the agent runs, as a compact terminal: where it runs and how it is going in the header, then each
   command with its output streaming in under it, and an exit code or a check with how long it took. Output longer than
   five lines folds to its last four. The output is code (12px mono on a 1.8 line height); everything around it, the header,
   the times, the agent's notes and the summary, is in the interface's own type. It sits on two columns (owner, 18 Nov): the
   header's terminal mark, each command's $ (an edit's pencil, a note's spark) and the summary's mark are centred in one 16px
   column 16px in, and the directory, the commands, their output and the notes' words all start 8px after it. It keeps no room
   for output still to come (owner, 17 Nov): the terminal grows as lines arrive (grow()) up to 420px, then its output scrolls
   under the header and keeps to its newest line */
.dm-tmx{display:flex;flex-direction:column;max-height:420px;overflow:hidden}
.dm-tmx>.dm-grow{max-height:420px;min-height:0}
/* the head's controls (Copy, the tallest, at 30px) have 16px above them and 16px down to the hairline, as a footer's do */
.dm-tmx-h{display:flex;align-items:center;gap:var(--dm-s-2);height:calc(30px + 2 * var(--dm-s-4) + 1px);flex:none;padding:0 var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-tmx-ic{width:16px;display:grid;place-items:center;color:var(--dm-fg2);flex:none}
/* (the directory and the state take a line as tall as their letters, so their words sit on the header's centre line) */
.dm-tmx-cwd{min-width:0;flex:0 1 auto;font-size:12.5px;line-height:15px;color:var(--dm-fg2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-tmx-st{display:inline-flex;align-items:center;gap:6px;min-width:0;font-size:12px;line-height:15px;white-space:nowrap}
.dm-tmx-st .dm-g{display:grid;place-items:center;flex:none}
.dm-tmx-st .dm-spin{width:10px;height:10px}
.dm-tmx-h .dm-sp{flex:1}
/* a narrow card (a phone) keeps every part of the head whole, so the state never runs into Stop (fix, 23 Nov): the state, Stop
   and Copy never shrink; under 300px Stop shows its icon only (its label stays for screen readers), and under 250px the
   directory, which by then would show only an ellipsis, gives way */
.dm-tmx-h{container:tmxh/inline-size}
.dm-tmx-st,.dm-tmx-h :is(.dm-pill,.dm-ib){flex:none}
@container tmxh (max-width:300px){.dm-tmx .dm-tmx-h .dm-pill.dm-tmx-stop{width:28px;padding:0;gap:0;justify-content:center;font-size:0}}
@container tmxh (max-width:250px){.dm-tmx-cwd{display:none}}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.dm-tmx :is(.dm-ib,.dm-pill):active,:root[data-style="clean"] .dm-tmx .dm-ib:active,:root [data-style="clean"] .dm-tmx .dm-ib:active,:root [data-style="clean"].dm-tmx .dm-ib:active{transform:none}
/* Copy's tick is the vivid mark green, in place of its icon and at its size (owner, 18 Nov) */
.dm-tmx .dm-ib.dm-copied{color:var(--dm-ok-mark)!important}
@media (hover:hover) and (pointer:fine){.dm-tmx .dm-ib.dm-copied:hover{color:var(--dm-ok-mark)!important}}
.dm-tmx-body{flex:1 1 auto;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:var(--dm-s-2) 0;font-size:12px;line-height:1.8;scrollbar-width:thin;scrollbar-color:var(--dm-rail) transparent}
.dm-tmx-body::-webkit-scrollbar{width:8px}
.dm-tmx-body::-webkit-scrollbar-track{background:transparent}
.dm-tmx-body::-webkit-scrollbar-thumb{background:var(--dm-rail);border:2px solid transparent;background-clip:padding-box;border-radius:var(--dm-r-pill)}
:root:not([data-style="soft"],[data-style="clean"]) .dm-tmx-body:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::-webkit-scrollbar-thumb{border-radius:0}
/* the commands, their output and an edit's lines are code: mono, the only place it is used */
.dm-tmx-body code{font:inherit;font-family:var(--dm-mono);font-size:12px}
.dm-tmx-blk+.dm-tmx-blk{margin-top:var(--dm-s-1)}
/* (a whole-pixel line, so the command's code and its time, in their two fonts, land on one baseline) */
.dm-tmx-cmd{display:flex;align-items:center;gap:var(--dm-s-2);padding:0 var(--dm-s-4);line-height:22px}
.dm-tmx-p{width:16px;flex:none;display:grid;place-items:center;color:var(--dm-fg2)}
code.dm-tmx-p{font-weight:500;color:var(--dm-accent-fg,var(--dm-fg))}
.dm-tmx-c{flex:1;min-width:0;font-weight:500;color:var(--dm-fg);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-tmx-m{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:var(--dm-muted);white-space:nowrap;flex:none}
.dm-tmx-m .dm-g{display:grid;place-items:center}
.dm-tmx-m .dm-spin{width:10px;height:10px}
.dm-tmx-m .dm-ok{display:grid;color:var(--dm-ok-mark)}
.dm-tmx-m .dm-add{color:var(--dm-add)}.dm-tmx-m .dm-del{color:var(--dm-del)}
/* the output wraps inside the panel, so a long line never pushes the page sideways */
.dm-tmx-o{display:block;padding:0 var(--dm-s-4) 0 40px;color:var(--dm-fg2);white-space:pre-wrap;overflow-wrap:anywhere}
.dm-tmx-l{display:block}
.dm-tmx-l.dm-ok{color:var(--dm-ok)}.dm-tmx-l.dm-bad{color:var(--dm-bad)}.dm-tmx-l.dm-mu{color:var(--dm-muted)}
/* a streaming log never pulses (owner, 26 Nov): each line, command, note and edit that arrives opens its own height in 180ms
   (between the motion pieces' quick and calm times, about one line's arrival apart) as its words fade in, and the line that folds
   away above the last four closes in the same time and curve, so the log's height moves in one continuous line and the card,
   which follows its content frame by frame (growFit()), never lags behind it: the newest line never sits in the card's padding
   and the cursor under it never hides. A line moved into the folded part stays still (.still). Where a browser can't ease to
   an auto height, lines arrive as before and the card springs to them */
@keyframes dm-tmxopen{from{height:0;margin-top:0;margin-bottom:0;opacity:0;clip-path:inset(0 0 100% 0)}to{clip-path:inset(0)}}
@keyframes dm-tmxshut{from{clip-path:inset(0)}to{height:0;margin-top:0;margin-bottom:0;opacity:0;clip-path:inset(0 0 100% 0)}}
@supports (interpolate-size:allow-keywords){
  .dm-tmx-body{interpolate-size:allow-keywords}
  .dm-tmx-body>:is(.dm-tmx-blk,.dm-tmx-note),.dm-tmx-o>.dm-tmx-l:not(.dm-still),.dm-tmx-df,.dm-tmx-more.dm-opens{animation:dm-tmxopen 180ms var(--dm-ease) backwards}
  .dm-tmx-o>.dm-tmx-l.dm-gone{animation:dm-tmxshut 180ms var(--dm-ease) forwards}
}
/* (its hover fill ends on the content's 16px edge, as the output above it does) */
.dm-tmx-more{display:flex;align-items:center;gap:6px;width:calc(100% - 48px);margin:0 var(--dm-s-4) 0 32px;padding:0 8px;border-radius:var(--dm-r-sm);font-size:12px;line-height:inherit;text-align:left;color:var(--dm-muted);transition:color var(--dm-t-fast),background-color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-tmx-more:hover{color:var(--dm-fg);background:var(--dm-row)}}
/* its motion (the core's motion pieces, owner, 26 Nov): Stop, Copy and the folded lines' button press at once (.mx-press); Copy's
   tick, and a mark that changes (the header's and each command's spinner into its tick, Exit tag or Stopped), crossfade in place
   (.mx-ic, iconSwap()); the terminal grows on the spring (.mx-grow) */
.dm-tmx-more .dm-sp{flex:1}
.dm-tmx-more svg{transition:transform var(--dm-t) var(--dm-ease)}
.dm-tmx-more[aria-expanded="true"] svg{transform:rotate(180deg)}
/* folded lines are hidden once they have folded away, so nothing measures the clipped part as if it were drawn */
.dm-tmx-blk .dm-fold.dm-shut>*{visibility:hidden;transition:visibility 0s var(--dm-t)}
/* what the agent says between commands: its spark in the marks' column and its words on the commands' column, shimmering
   while it is still working it out */
.dm-tmx-note{display:flex;gap:var(--dm-s-2);margin:var(--dm-s-2) var(--dm-s-4);font-size:12.5px;line-height:1.5;color:var(--dm-fg2)}
.dm-tmx-note>svg{flex:none;margin:3px 2px 0;color:var(--dm-accent-fg,var(--dm-accent))}
.dm-tmx-note .dm-shim{font-size:inherit}
/* once the run is over, the line at the foot: its mark in the marks' column and how many commands ran (a finished line has
   no clock, owner, 18 Nov) */
.dm-tmx-f{display:flex;align-items:center;gap:var(--dm-s-2);padding:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px}
.dm-tmx-f .dm-g{width:16px;display:grid;place-items:center;flex:none;color:var(--dm-ok-mark)}
.dm-tmx-f.dm-stop .dm-g{color:var(--dm-muted)}.dm-tmx-f.dm-bad .dm-g{color:var(--dm-bad-mark)}
/* the run's state in the header: a neutral tag while it runs, its words shimmering as every loader's do (owner, 19 Nov), then
   the green tint once it passes or the red one if it failed */
.dm-tmx-st{height:22px;padding:0 var(--dm-s-2);border-radius:var(--dm-r-tag);background:var(--dm-chip-fill);color:var(--dm-fg2);transition:background .3s,color .3s}
.dm-tmx-sv.dm-shim{font-size:inherit}
.dm-tmx-st.dm-ok,.dm-tmx-st.dm-ok .dm-g{background:var(--dm-ok-bg);color:var(--dm-ok)}
.dm-tmx-st.dm-bad,.dm-tmx-st.dm-bad .dm-g{background:var(--dm-bad-bg);color:var(--dm-bad)}
/* while it runs, a light sweeps along the header's lower edge */
.dm-tmx-h{position:relative}
.dm-tmx-h::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:1px;background:linear-gradient(90deg,transparent,var(--dm-accent-mark,var(--dm-accent)),transparent) 0 0/40% 100% no-repeat;opacity:0;transition:opacity .4s;pointer-events:none}
.dm-tmx.dm-live .dm-tmx-h::after{opacity:1;animation:dm-tmxsweep 1.8s var(--dm-ease-io) infinite}
@keyframes dm-tmxsweep{from{background-position:-60% 0}to{background-position:160% 0}}
/* each command and edit has a line down its left: neutral grey, the accent while it runs and red if it failed (colour only
   where it means something: what is running, and what failed) */
.dm-tmx-blk{position:relative}
.dm-tmx-blk::before{content:"";position:absolute;left:7px;top:4px;bottom:4px;width:2px;border-radius:1px;background:var(--dm-rail);transition:background .3s}
.dm-tmx-blk[data-s="run"]::before{background:var(--dm-accent-mark,var(--dm-accent));animation:dm-tmxpulse 1.4s var(--dm-ease-io) infinite}
.dm-tmx-blk[data-s="bad"]::before{background:var(--dm-bad-mark)}
@keyframes dm-tmxpulse{50%{opacity:.35}}
/* an edit shows the lines it changed, removed in red and added in green, each on its own tint; the words start on the
   output's column, their tint reaching 8px out round them */
.dm-tmx-df{display:block;margin:2px var(--dm-s-4) var(--dm-s-1) 32px;border-radius:var(--dm-r-sm);overflow:hidden}
.dm-tmx-df span{display:block;padding:1px var(--dm-s-2);white-space:pre-wrap;overflow-wrap:anywhere;color:var(--dm-fg2)}
.dm-tmx-df .dm-a{background:color-mix(in srgb,var(--dm-add) 10%,transparent)}.dm-tmx-df .dm-a::first-letter{color:var(--dm-add)}
.dm-tmx-df .dm-d{background:color-mix(in srgb,var(--dm-del) 10%,transparent)}.dm-tmx-df .dm-d::first-letter{color:var(--dm-del)}
/* a block cursor blinks after the newest line while the run goes on */
.dm-tmx.dm-live .dm-tmx-body::after{content:"";display:block;width:7px;height:14px;margin:var(--dm-s-1) 0 0 40px;background:var(--dm-fg2);animation:dm-bpblink 1.1s steps(1,end) infinite}
:root:not([data-style="soft"],[data-style="clean"]) .dm-tmx-h:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::after{background:repeating-linear-gradient(90deg,var(--dm-accent-mark) 0 6px,transparent 6px 12px);animation:dm-tmxmarch .6s steps(4) infinite}
@keyframes dm-tmxmarch{to{background-position:12px 0}}
:root:not([data-style="soft"],[data-style="clean"]) .dm-tmx-blk:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::before{width:1px}
:root:not([data-style="soft"],[data-style="clean"]) .dm-tmx-blk[data-s="run"]:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::before{animation:dm-bpblink 1.1s steps(1,end) infinite}
/* Clean (owner, 18 Nov): an off-white head strip with the directory and the run's state, Stop and Copy 16px from the card's
   edges and the strip's hairline as 28px pills (owner, 23 Nov); the output on white, 16px in, with no coloured lines (the mark at each command's end says how it went)
   and the $ in grey; and once the run is over, the summary as the off-white foot strip */
:root[data-style="clean"] .dm-tmx-h,:root [data-style="clean"] .dm-tmx-h,:root [data-style="clean"].dm-tmx-h{height:calc(28px + 2 * var(--dm-strip-y) + 1px);padding:0 16px;background:var(--dm-strip);border-bottom-color:var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .dm-tmx-h::after,:root [data-style="clean"] .dm-tmx-h::after,:root [data-style="clean"].dm-tmx-h::after,:root[data-style="clean"] .dm-tmx-blk::before,:root [data-style="clean"] .dm-tmx-blk::before,:root [data-style="clean"].dm-tmx-blk::before{display:none}
:root[data-style="clean"] .dm-tmx .dm-ib,:root [data-style="clean"] .dm-tmx .dm-ib,:root [data-style="clean"].dm-tmx .dm-ib{width:28px;height:28px}
:root[data-style="clean"] .dm-tmx-body,:root [data-style="clean"] .dm-tmx-body,:root [data-style="clean"].dm-tmx-body{padding:12px 0}
:root[data-style="clean"] :where([data-dm],.dm-tip,.dm-kbx-k.dm-ghost) code.dm-tmx-p,:root [data-style="clean"] :where([data-dm],.dm-tip,.dm-kbx-k.dm-ghost) code.dm-tmx-p,:root [data-style="clean"]:where([data-dm],.dm-tip,.dm-kbx-k.dm-ghost) code.dm-tmx-p{color:var(--dm-muted)}
:root[data-style="clean"] .dm-tmx-note>svg,:root [data-style="clean"] .dm-tmx-note>svg,:root [data-style="clean"].dm-tmx-note>svg{color:var(--dm-fg2)}
:root[data-style="clean"] .dm-tmx-f,:root [data-style="clean"] .dm-tmx-f,:root [data-style="clean"].dm-tmx-f{padding:var(--dm-strip-y) 16px;line-height:28px;font-size:12.5px;background:var(--dm-strip);border-top-color:var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .dm-tmx-f:not(.dm-stop,.dm-bad) .dm-g,:root [data-style="clean"] .dm-tmx-f:not(.dm-stop,.dm-bad) .dm-g,:root [data-style="clean"].dm-tmx-f:not(.dm-stop,.dm-bad) .dm-g{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}
:root[data-style="clean"] .dm-tmx-st,:root [data-style="clean"] .dm-tmx-st,:root [data-style="clean"].dm-tmx-st{transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
/* (on the off-white strip the state's grey chip is a step darker, so it shows as a chip does on white) */
:root[data-style="clean"] .dm-tmx-st:not(.dm-ok,.dm-bad),:root [data-style="clean"] .dm-tmx-st:not(.dm-ok,.dm-bad),:root [data-style="clean"].dm-tmx-st:not(.dm-ok,.dm-bad){background:var(--dm-chip-fill-h)}
:root[data-style="clean"] .dm-tmx-more,:root [data-style="clean"] .dm-tmx-more,:root [data-style="clean"].dm-tmx-more{transition:color var(--dm-t-fast) var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease)}
